#!/usr/bin/env node

/**
 * Phase 391 -- Identify scan code 0x4E and find the 2ND translation table caller
 *
 * Session 390 found that scan code 0x4E triggers a kbdKey/kbdToken swap at
 * 0x030300. 0x4E = 78 decimal, which exceeds the natural 7×8 = 56 range,
 * so it may be synthetic (generated by the translation table at 0x09F79B).
 *
 * This probe:
 *   1. Searches ROM for 3-byte LE references to 0x09F79B and 0x09F7D3
 *   2. Searches for LD A,0x4E (3E 4E) near stores to D007E0 or D0058C
 *   3. Decodes what 0x4E means in the translation table
 *   4. Searches for CALL/JP to 0x02FF0B (GetCSC lookup entry)
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROM_PATH = path.join(__dirname, "ROM.rom");

const rom = fs.readFileSync(ROM_PATH);

function hex(v, digits = 6) {
  return "0x" + v.toString(16).padStart(digits, "0").toUpperCase();
}

function hex2(v) {
  return "0x" + (v & 0xFF).toString(16).padStart(2, "0").toUpperCase();
}

// ---- Helper: search ROM for a 3-byte little-endian pattern ----

function searchBytes3(b0, b1, b2, label) {
  const hits = [];
  for (let i = 0; i < rom.length - 2; i++) {
    if (rom[i] === b0 && rom[i + 1] === b1 && rom[i + 2] === b2) {
      hits.push(i);
    }
  }
  return hits;
}

// ---- Helper: search ROM for a 2-byte pattern ----

function searchBytes2(b0, b1) {
  const hits = [];
  for (let i = 0; i < rom.length - 1; i++) {
    if (rom[i] === b0 && rom[i + 1] === b1) {
      hits.push(i);
    }
  }
  return hits;
}

// ---- Helper: search ROM for a 4-byte pattern ----

function searchBytes4(b0, b1, b2, b3) {
  const hits = [];
  for (let i = 0; i < rom.length - 3; i++) {
    if (rom[i] === b0 && rom[i + 1] === b1 && rom[i + 2] === b2 && rom[i + 3] === b3) {
      hits.push(i);
    }
  }
  return hits;
}

// ---- Helper: dump context bytes around an address ----

function contextDump(addr, before = 8, after = 8) {
  const start = Math.max(0, addr - before);
  const end = Math.min(rom.length, addr + after);
  const bytes = [];
  for (let i = start; i < end; i++) {
    const prefix = i === addr ? "[" : " ";
    const suffix = i === addr ? "]" : " ";
    bytes.push(prefix + rom[i].toString(16).padStart(2, "0") + suffix);
  }
  return `${hex(start)}: ${bytes.join("")}`;
}

// ============================================================
// 1. Search for references to 0x09F79B and 0x09F7D3
// ============================================================

console.log("=" .repeat(80));
console.log("1. ROM references to translation table addresses");
console.log("=" .repeat(80));

// 0x09F79B in LE = 9B F7 09
const refs9F79B = searchBytes3(0x9B, 0xF7, 0x09);
console.log(`\nReferences to 0x09F79B (table base): ${refs9F79B.length} hits`);
for (const addr of refs9F79B) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 6, 10)}`);
}

// 0x09F7D3 in LE = D3 F7 09  (table + 0x38 = 2ND section)
const refs9F7D3 = searchBytes3(0xD3, 0xF7, 0x09);
console.log(`\nReferences to 0x09F7D3 (2ND section): ${refs9F7D3.length} hits`);
for (const addr of refs9F7D3) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 6, 10)}`);
}

// Also check 0x09F80B (alpha section, +0x70) and 0x09F843 (alpha+2nd, +0xA8)
const refs9F80B = searchBytes3(0x0B, 0xF8, 0x09);
console.log(`\nReferences to 0x09F80B (Alpha section): ${refs9F80B.length} hits`);
for (const addr of refs9F80B) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 6, 10)}`);
}

const refs9F843 = searchBytes3(0x43, 0xF8, 0x09);
console.log(`\nReferences to 0x09F843 (Alpha+2ND section): ${refs9F843.length} hits`);
for (const addr of refs9F843) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 6, 10)}`);
}

// ============================================================
// 2. Search for LD A,0x4E (3E 4E) near stores to D007E0/D0058C
// ============================================================

console.log("\n" + "=" .repeat(80));
console.log("2. LD A,0x4E (3E 4E) occurrences + proximity to key RAM addresses");
console.log("=" .repeat(80));

const ldA4E = searchBytes2(0x3E, 0x4E);
console.log(`\nLD A,0x4E occurrences: ${ldA4E.length}`);

// For each hit, check if D007E0 or D0058C appears nearby (within 32 bytes)
for (const addr of ldA4E) {
  // Check wider context for known addresses
  const start = Math.max(0, addr - 32);
  const end = Math.min(rom.length - 2, addr + 32);
  let nearbyNotes = [];

  for (let i = start; i < end; i++) {
    // D007E0 in LE = E0 07 D0
    if (rom[i] === 0xE0 && rom[i + 1] === 0x07 && rom[i + 2] === 0xD0) {
      nearbyNotes.push(`D007E0 at ${hex(i)}`);
    }
    // D0058C in LE = 8C 05 D0
    if (rom[i] === 0x8C && rom[i + 1] === 0x05 && rom[i + 2] === 0xD0) {
      nearbyNotes.push(`D0058C at ${hex(i)}`);
    }
  }

  const notes = nearbyNotes.length > 0 ? ` ** NEARBY: ${nearbyNotes.join(", ")}` : "";
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 16)}${notes}`);
}

// Also search for CP 0x4E (FE 4E) which is used in the comparison at 0x0236F9
const cp4E = searchBytes2(0xFE, 0x4E);
console.log(`\nCP 0x4E (FE 4E) occurrences: ${cp4E.length}`);
for (const addr of cp4E) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 16)}`);
}

// ============================================================
// 3. Decode 0x4E in the translation table
// ============================================================

console.log("\n" + "=" .repeat(80));
console.log("3. Decode 0x4E in the translation table at 0x09F79B");
console.log("=" .repeat(80));

const TABLE_ADDR = 0x09F79B;
const SECTION_NAMES = ["Unmodified", "2nd", "Alpha", "Alpha+2nd"];
const SECTION_OFFSETS = [0x00, 0x38, 0x70, 0xA8];
const MAX_SC = 0x38; // 56 entries per section

// First: is 0x4E an OUTPUT of the table? (scan code -> key code mapping)
console.log("\n3a. Entries in the table that OUTPUT 0x4E:");
let found4EOutput = false;
for (let s = 0; s < 4; s++) {
  for (let sc = 0; sc <= MAX_SC; sc++) {
    const keyCode = rom[TABLE_ADDR + SECTION_OFFSETS[s] + sc];
    if (keyCode === 0x4E) {
      console.log(`  Section ${SECTION_NAMES[s]} (offset +${hex2(SECTION_OFFSETS[s])}), scancode ${hex2(sc)} -> 0x4E`);
      found4EOutput = true;
    }
  }
}
if (!found4EOutput) {
  console.log("  (none found — 0x4E is not an output of this table)");
}

// Second: is 0x4E an INPUT scan code? (would be out of range since max is 0x38)
console.log("\n3b. 0x4E as an input scan code:");
if (0x4E <= MAX_SC) {
  for (let s = 0; s < 4; s++) {
    const keyCode = rom[TABLE_ADDR + SECTION_OFFSETS[s] + 0x4E];
    console.log(`  Section ${SECTION_NAMES[s]}: scancode 0x4E -> ${hex2(keyCode)}`);
  }
} else {
  console.log(`  0x4E (${0x4E}) > MAX_SC (${MAX_SC}) — out of range as a table input`);
  console.log(`  This suggests 0x4E is NOT a raw scan code from the table`);
}

// Third: dump the full table for reference, highlighting any entries >= 0x39
console.log("\n3c. All table entries with value >= 0x39 (above natural scan code range):");
for (let s = 0; s < 4; s++) {
  const highEntries = [];
  for (let sc = 0; sc <= MAX_SC; sc++) {
    const keyCode = rom[TABLE_ADDR + SECTION_OFFSETS[s] + sc];
    if (keyCode >= 0x39) {
      highEntries.push(`sc=${hex2(sc)}->${hex2(keyCode)}`);
    }
  }
  if (highEntries.length > 0) {
    console.log(`  ${SECTION_NAMES[s]}: ${highEntries.join(", ")}`);
  }
}

// Fourth: the OS scan code formula — what physical key is 0x4E?
console.log("\n3d. OS scan code formula: scancode = (6-group)*8 + bit + 1");
console.log("  0x4E = 78. Solving: (6-group)*8 + bit + 1 = 78");
console.log("  (6-group)*8 + bit = 77");
console.log("  group=0(unused): 6*8+bit=48+bit -> bit=29 (impossible, max 7)");
console.log("  No valid (group,bit) pair — 0x4E is SYNTHETIC");

// ============================================================
// 4. Search for CALL/JP to 0x02FF0B (GetCSC lookup entry)
// ============================================================

console.log("\n" + "=" .repeat(80));
console.log("4. CALL/JP to 0x02FF0B (GetCSC lookup entry)");
console.log("=" .repeat(80));

// CALL 0x02FF0B = CD 0B FF 02
const callGetCSC = searchBytes4(0xCD, 0x0B, 0xFF, 0x02);
console.log(`\nCALL 0x02FF0B: ${callGetCSC.length} hits`);
for (const addr of callGetCSC) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

// JP 0x02FF0B = C3 0B FF 02
const jpGetCSC = searchBytes4(0xC3, 0x0B, 0xFF, 0x02);
console.log(`\nJP 0x02FF0B: ${jpGetCSC.length} hits`);
for (const addr of jpGetCSC) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

// Also search for the address without opcode prefix (might be in a jump table)
const rawRef02FF0B = searchBytes3(0x0B, 0xFF, 0x02);
console.log(`\nRaw 3-byte references to 0x02FF0B: ${rawRef02FF0B.length} hits`);
for (const addr of rawRef02FF0B) {
  // Show the byte before to identify the opcode
  const opByte = addr > 0 ? hex2(rom[addr - 1]) : "??";
  console.log(`  ${hex(addr)} (opcode before: ${opByte})  ${contextDump(addr, 6, 8)}`);
}

// ============================================================
// 5. Bonus: search for references to 0x030300 (the kbdKey/kbdToken swap)
// ============================================================

console.log("\n" + "=" .repeat(80));
console.log("5. Bonus: CALL/JP to 0x030300 (kbdKey/kbdToken swap routine)");
console.log("=" .repeat(80));

const call030300 = searchBytes4(0xCD, 0x00, 0x03, 0x03);
console.log(`\nCALL 0x030300: ${call030300.length} hits`);
for (const addr of call030300) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

const jp030300 = searchBytes4(0xC3, 0x00, 0x03, 0x03);
console.log(`\nJP 0x030300: ${jp030300.length} hits`);
for (const addr of jp030300) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

// ============================================================
// 6. Bonus: search for references to 0x0236F9 (event builder with 0x4E compare)
// ============================================================

console.log("\n" + "=" .repeat(80));
console.log("6. Bonus: CALL/JP to 0x0236F9 (event builder)");
console.log("=" .repeat(80));

const call0236F9 = searchBytes4(0xCD, 0xF9, 0x36, 0x02);
console.log(`\nCALL 0x0236F9: ${call0236F9.length} hits`);
for (const addr of call0236F9) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

const jp0236F9 = searchBytes4(0xC3, 0xF9, 0x36, 0x02);
console.log(`\nJP 0x0236F9: ${jp0236F9.length} hits`);
for (const addr of jp0236F9) {
  console.log(`  ${hex(addr)}  ${contextDump(addr, 4, 12)}`);
}

console.log("\n" + "=" .repeat(80));
console.log("Done.");
console.log("=" .repeat(80));
